function saveRecentCalculation(d,v,r){try{const old=safeHistory(),entry={id:d.id,name:d.n,at:Date.now(),inputs:v,ui:{displayCurrency:$("#display-currency")?.value||activeCurrency,countryPreset:$("#country-preset")?.value||"",taxProfile:$("#tax-profile")?.value||"",assetSelector:$("#asset-selector")?.value||"",assetBaselinePrice:$("#asset-baseline-price")?.value||""},result:String(r.main)};if(old[0]&&old[0].id===entry.id&&JSON.stringify(old[0].inputs)===JSON.stringify(v)&&JSON.stringify(old[0].ui||{})===JSON.stringify(entry.ui))old.shift();localStorage.setItem("finpulse-history-v1",JSON.stringify([entry,...old].slice(0,10)))}catch{}renderHistory()}
