function renderBreakdown(rows,d){
 const panel=$("#breakdown-panel"),el=$("#breakdown-table");if(!panel||!el)return;
 if(!Array.isArray(rows)||!rows.length){panel.hidden=true;return}
 panel.hidden=false;
 const keys=Object.keys(rows[0]),labels={component:"Tax component",portion:"Taxable band amount",taxableIncome:"Taxable income",rate:"Tax rate",marginalRate:"Marginal rate",credit:"Credit",tax:"Tax due",item:toolUi("breakdownItem","Breakdown item"),value:toolUi("amount","Amount")};
 const html="<div class='schedule-scroll' tabindex='0' role='region' aria-label='"+escapeHtml(toolUi("breakdownRegion","Scrollable calculation breakdown"))+"'><table><thead><tr>"+keys.map(k=>"<th>"+escapeHtml(labels[k]||k)+"</th>").join("")+"</tr></thead><tbody>"+rows.map(row=>"<tr>"+keys.map(k=>{const v=row[k];return "<td>"+(typeof v==="number"?(["rate","marginalRate"].includes(k)?num(v)+"%":fmt(v)):escapeHtml(v??"—"))+"</td>"}).join("")+"</tr>").join("")+"</tbody></table></div>";
 el.innerHTML=html;
}
function renderSchedule(schedule,d){
 const panel=$("#schedule-panel"),el=$("#schedule-table");if(!panel||!el)return;
 if(!schedule||!schedule.monthly||!schedule.monthly.length){panel.hidden=true;return}
 panel.hidden=false;let mode="monthly",which="primary";
 const draw=()=>{
  const chosen=which==="comparison"&&schedule.comparison?schedule.comparison:schedule,rows=mode==="yearly"?chosen.yearly:chosen.monthly.slice(0,12);
  const labels={month:toolUi("month","Month"),year:toolUi("year","Year"),openingBalance:toolUi("openingBalance","Opening balance"),payment:toolUi("payments","Payments"),principal:toolUi("principal","Principal"),interest:toolUi("interest","Interest"),closingBalance:toolUi("closingBalance","Closing balance")};
  const columns=(chosen.columns||schedule.columns||[{key:mode==="yearly"?"year":"month",label:mode==="yearly"?"Year":"Month"},{key:"openingBalance",label:"Opening balance"},{key:"payment",label:"Payments"},{key:"principal",label:"Principal"},{key:"interest",label:"Interest"},{key:"closingBalance",label:"Closing balance"}]).map(column=>({...column,label:labels[column.key]||column.label}));
  let html="<div class='buttons'><button class='btn secondary' type='button' data-mode='monthly'>"+escapeHtml(toolUi("monthly","Monthly"))+"</button><button class='btn secondary' type='button' data-mode='yearly'>"+escapeHtml(toolUi("yearly","Yearly"))+"</button>";
  if(schedule.comparison)html+="<button class='btn secondary' type='button' data-set='primary'>"+escapeHtml(toolUi("primaryScenario","Primary scenario"))+"</button><button class='btn secondary' type='button' data-set='comparison'>"+escapeHtml(schedule.comparison.label||toolUi("comparison","Comparison"))+"</button>";
  html+="</div><p class='note'>"+escapeHtml(mode==="monthly"?toolUi("first12","First 12 monthly periods shown. Choose Yearly for annual totals."):toolUi("yearlyTotals","Yearly totals are aggregated from monthly projections; the final year may be partial."))+"</p><div class='schedule-scroll' tabindex='0' role='region' aria-label='"+escapeHtml(toolUi("scheduleRegion","Scrollable calculation schedule"))+"'><table><thead><tr>"+columns.map(c=>"<th>"+escapeHtml(c.label)+"</th>").join("")+"</tr></thead><tbody>";
  html+=rows.map(row=>"<tr>"+columns.map(c=>"<td>"+(c.key==="month"||c.key==="year"?row[c.key]:fmt(row[c.key]))+"</td>").join("")+"</tr>").join("");
  html+="</tbody></table></div>";el.innerHTML=html;
  el.querySelectorAll("[data-mode]").forEach(b=>b.onclick=()=>{mode=b.dataset.mode;draw()});
  el.querySelectorAll("[data-set]").forEach(b=>b.onclick=()=>{which=b.dataset.set;draw()});
 };draw();
}
function relatedMarkup(d){const group=directoryMapping?.categories.find(category=>category.subcategories.some(sub=>sub.toolIds.includes(d.id)));const sub=group?.subcategories.find(item=>item.toolIds.includes(d.id));const pool=sub?sub.toolIds.map(id=>D.find(tool=>tool.id===id)).filter(tool=>tool&&tool.id!==d.id):D.filter(tool=>tool.id!==d.id&&tool.c===d.c);return pool.length?"<p class='related-context'>"+escapeHtml(sub?.name||group?.name||d.c)+"</p><ul>"+pool.map(tool=>"<li><a href='?tool="+encodeURIComponent(tool.id)+"#tools'>"+escapeHtml(tool.n)+"</a></li>").join("")+"</ul>":"<p class='note'>No other tools are listed in this subcategory yet.</p>"}
function escapeHtml(value){return String(value).replace(/[&<>"']/g,ch=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[ch]))}
function presetMarkup(d){const sets={"mortgage":["Conventional example","Higher down payment","Extra monthly"],"amortization":["15-year example","20-year example","Extra monthly"],"payoff":["No extra","+$100 monthly","+$300 monthly"],"refinance":["Lower rate","Shorter term","No closing costs"],"student-loan":["Standard only","+$50 monthly","+$100 monthly"],"compound":["5% return","7% return","10% return"],"savings":["3-year goal","5-year goal","No interest"],"retirement":["Conservative 4%","Base 6%","Higher 8%"],"401k":["No employer match","50% match","100% match"],"cash-flow":["3 months","12 months","24 months"],"business-roi":["Base case","Higher return","Loss scenario"],"break-even":["Base costs","Higher price","Narrow margin"],"freelance-project":["Standard quote","Higher scope","Higher contingency"],"freelancer-net-income":["Base year","Higher revenue","Lower reserve"],"margin":["Base margin","Thin margin","Operating loss"],"rental-yield":["Base property","Higher rent","Higher costs"],"emergency-fund":["3 months","6 months","9 months"],"net-worth":["Current snapshot","Higher assets","Higher debt"],"loan":["Standard payment","+$100 extra","+$250 extra"],"emi":["3-year term","5-year term","7-year term"],"car":["Standard payment","+$100 extra","+$250 extra"],"affordability":["Conservative","Balanced","Higher ratio"],"personal-loan":["Standard payment","+$100 extra","+$250 extra"]};const labels=d.presets?.map(p=>p.label)||sets[d.id];return labels?'<div class="preset-buttons"><span>Quick scenarios:</span>'+labels.map((x,i)=>'<button type="button" class="btn secondary" data-preset="'+i+'">'+x+'</button>').join("")+'</div>':""}
function seoMarkup(d){const batchFaqs=({"compound":[["How is compound growth calculated?","The model compounds monthly at the entered annual rate divided by 12 and adds deposits at month end."],["Are returns guaranteed?","No. The rate is an assumption for an illustration, not a guaranteed investment return."],["When are deposits added?","Deposits are added at the end of each month after that month's interest."],["Are taxes and fees included?","No. Taxes, fees and changing returns are excluded."]],"savings":[["How is the monthly deposit found?","The calculator solves the future-value annuity equation after growing current savings."],["When are deposits made?","At the end of each month in the projection."],["What if the goal is already funded?","The required monthly deposit is zero when projected current savings already meet the goal."],["Is the interest guaranteed?","No. The entered rate is an assumption."]],"retirement":[["How often is growth compounded?","Monthly, using the entered annual assumed return divided by 12."],["Are contributions made at month end?","Yes. Monthly contributions are added after that month's modeled growth."],["What is inflation-adjusted value?","Future value divided by (1 + assumed inflation rate) raised to the number of years."],["Does this predict retirement income?","No. It is an accumulation illustration and does not model withdrawals or taxes."]],"401k":[["How is the employer match calculated?","The model matches the lesser of the employee contribution rate and eligible salary percentage, multiplied by the match rate."],["Are annual contribution limits included?","No. Current IRS limits and catch-up rules are not applied."],["Does it model vesting?","No. Employer vesting, plan fees and taxes are excluded."],["Is the return guaranteed?","No. Investment return is a user-entered assumption."]],"ira":[["What is compared?","Simplified Roth and Traditional after-tax account values under the entered tax and return assumptions."],["Is the current tax saving reinvested?","No. The model explicitly excludes reinvestment of Traditional IRA tax savings."],["Are contribution limits checked?","No. Eligibility, income phase-outs and annual limits are not modeled."],["Is this tax advice?","No. It is an educational comparison, not individualized tax advice."]],"cash-flow":[["How is month-end cash calculated?","Opening cash plus that month's inflows minus that month's outflows."],["How are growth assumptions applied?","Each month's inflows and outflows grow by their separate monthly rates, compounded from the first month."],["Can the balance become negative?","Yes. Negative closing cash signals a funding gap under the entered assumptions."],["Does it replace accounting software?","No. Timing, receivables, taxes, financing and seasonality are excluded."]],"cd":[["How is maturity value estimated?","The entered APY is applied as an effective annual yield over the entered fraction of a year."],["Does the calculator include early withdrawal penalties?","No. Penalties, fees and taxes are excluded."],["Is the APY guaranteed?","Only the product terms can establish that. This calculator assumes the entered APY remains fixed."],["Does term need to be whole months?","Yes. The calculator accepts whole months only."]],"apy":[["What is APY?","Annual percentage yield expresses the effective annual return after compounding."],["How is APY derived?","It compounds the nominal periodic rate for the selected number of periods in one year."],["Does APY include fees?","No. Fees and changing rates are excluded."],["Can compounding frequency be fractional?","No. Enter a whole-number frequency within the supported range."]],"business-roi":[["What does ROI measure?","Simple ROI compares gain or loss with the initial investment."],["Is ROI annualized?","No. The calculator does not account for investment duration or cash-flow timing."],["Can ROI be negative?","Yes. An ending value below the initial investment produces a loss."],["Are future returns predicted?","No. It measures only the entered values."]],"break-even":[["What is contribution per unit?","Selling price per unit minus variable cost per unit."],["Why round up units?","The practical sales target rounds the exact break-even quantity upward to a whole unit."],["Are taxes and financing included?","No. Taxes, financing, product mix and capacity constraints are excluded."],["What if price is not above variable cost?","There is no positive contribution margin, so break-even volume cannot be calculated."]],"freelance-project":[["How is the quote calculated?","Labor and expenses are combined with contingency, then divided by one minus the target gross margin."],["Is margin the same as markup?","No. Margin is profit divided by selling price; markup is profit divided by cost."],["Does this include tax?","No. Tax, payment fees and scope changes are excluded."],["Does it recommend market rates?","No. It uses the hourly rate and assumptions you enter."]],"freelancer-net-income":[["How is net income estimated?","Revenue less expenses and a user-selected reserve on profit."],["Is the tax reserve an official tax estimate?","No. It is a user-entered planning percentage, not a jurisdictional tax calculation."],["Can expenses exceed revenue?","This simplified calculator rejects expenses above revenue."],["Are irregular income and quarterly taxes modeled?","No. It is an annual summary."]],"profit-margin":[["How is profit margin calculated?","Profit divided by revenue, multiplied by 100."],["How is markup calculated?","Profit divided by cost, multiplied by 100."],["Can margin be negative?","Yes. If costs exceed revenue, profit margin is negative."],["Does this include tax?","No. It is a simple revenue and cost calculation."]],"rental-yield":[["What is gross rental yield?","Annual scheduled rent divided by property purchase price."],["How is net operating income calculated?","Rent after vacancy allowance minus entered annual operating costs."],["Are mortgage payments included?","No. This is an unlevered operating yield estimate."],["Are capital expenses and tax included?","No. They are excluded from the simplified calculation."]],"emergency-fund":[["How is the target calculated?","Essential monthly expenses multiplied by the selected target months."],["What does coverage months mean?","Current savings divided by essential monthly expenses."],["Can the savings gap be zero?","Yes. It is zero when current savings meet or exceed the target."],["Is the target a universal rule?","No. It is a user-selected planning target, not a recommendation."]],"net-worth":[["What counts as an asset?","The calculator sums entered cash, investments, property, vehicles and other assets."],["What counts as a liability?","Entered mortgage, loans, cards and other liabilities."],["Can net worth be negative?","Yes. It is negative when entered liabilities exceed entered assets."],["How often should values be updated?","The calculator is a point-in-time snapshot; update entries when balances or values change."]],"income-tax":[["How is progressive tax calculated?","Each taxable income band is taxed at its own rate and the band taxes are added."],["Which tax year is used?","The calculator uses the selected supported 2026 jurisdiction profile."],["Are all deductions and credits included?","No. Only the configured allowances, entered deductions and supported components are modeled."],["Is this an official tax return?","No. It is an educational estimate; consult official guidance or a qualified tax professional."]],"currency":[["Where does the reference rate come from?","When available, the tool uses Frankfurter published reference rates; otherwise it can use a manually entered rate."],["Are these live bank rates?","No. Reference rates may differ from bank, card and transfer-provider quotes."],["How is the provider fee applied?","The entered percentage fee is deducted from the gross converted amount."],["Are recipient-side fees included?","No. Only the entered provider fee is modeled."]],"loan":[["How is the monthly payment calculated?","A fixed-rate reducing-balance payment is calculated from principal, monthly rate and number of months."],["How does an extra payment work?","The extra amount is applied to principal after the scheduled payment."],["Does the schedule include lender fees?","No. Fees and lender-specific payment timing are excluded unless separately entered."],["Why can the payoff take fewer months?","The extra principal reduces the balance used to calculate later interest."]],"emi":[["What does EMI mean?","Equated monthly instalment: a fixed payment for a fixed-rate reducing-balance loan."],["Does EMI include fees and insurance?","No. It models principal and interest only."],["What happens at zero interest?","The principal is divided evenly by the number of monthly instalments."],["Can actual lender EMI differ?","Yes. Fees, dates, rounding and rate changes may affect lender figures."]],"percentage":[["How do I calculate a percentage of a number?","Multiply the number by the percentage and divide by 100."],["How is percentage change calculated?","Subtract the original value from the new value, divide by the absolute original value and multiply by 100."],["Can percentage change start from zero?","No. Percentage change from zero is undefined."],["What does reverse percentage find?","It finds the base value for which the entered amount represents the selected percentage."]],"tip":[["How is the tip calculated?","Bill amount multiplied by the entered tip percentage."],["How is the bill split?","The bill plus tip is divided evenly among the rounded whole-person count."],["Does it include taxes?","Only the bill amount entered is used; tax and service rules are not inferred."],["Can I change currency?","Use the currency selector for display; the arithmetic is currency-neutral."]],"car":[["How is the vehicle loan principal calculated?","Vehicle price less down payment and trade-in, plus fees entered as financed."],["Can I model extra payments?","Yes. Extra monthly payments are applied to principal after the scheduled payment."],["Are taxes and registration included?","Only fees entered in the calculator are included."],["Does it model a balloon payment?","No. It uses a fixed-rate reducing-balance schedule."]],"freelance":[["How is the hourly rate estimated?","The annual revenue target is divided by annual billable hours."],["Are business costs included?","Yes. Entered annual costs are included in the revenue target."],["Is the tax reserve an actual tax calculation?","No. It is a user-entered planning percentage."],["Does it account for unpaid time?","Only through the billable-hours and working-weeks assumptions you enter."]],"margin":[["How is profit margin calculated?","Profit divided by revenue, multiplied by 100."],["How is markup different?","Markup divides profit by cost, while margin divides profit by revenue."],["Can profit margin be negative?","Yes. Costs above revenue produce a loss and negative margin."],["What if revenue is zero?","Margin is undefined because revenue is the denominator."]],"affordability":[["How is the housing budget estimated?","The calculator uses the lower of the housing-cost ratio and debt-to-income capacity."],["Are taxes, insurance and HOA included?","Entered monthly property tax, insurance and HOA are deducted before estimating principal-and-interest capacity."],["Does it guarantee mortgage approval?","No. Lender underwriting, credit, reserves and local costs are not modeled."],["What does maximum home price include?","The estimated maximum loan plus the available down payment."]],"personal-loan":[["How is the origination fee handled?","The fee is assumed deducted from requested principal to estimate net proceeds."],["What is fee-adjusted annualized cost?","An estimated annualized rate solved from net proceeds and the scheduled payment stream."],["Is it the lender's official APR?","No. Other charges, timing and disclosure rules may change the official APR."],["How does an extra payment affect payoff?","It reduces principal and can lower total interest and repayment time."]],"simple-interest":[["What is simple interest?","Interest calculated on the original principal, not on accumulated interest."],["How does the day-count basis affect the result?","The year fraction is days divided by the selected 360, 365 or 366 basis."],["Is the compound comparison the same method?","No. It is shown separately as an illustrative annual-compounding comparison."],["Are fees included?","No. Only principal, rate, days and day-count basis are modeled."]],"inflation":[["How is future cost estimated?","Current amount multiplied by one plus the annual inflation rate raised to the number of years."],["Is the inflation rate a forecast?","No. It is a constant user-entered scenario."],["What is purchasing power here?","The entered amount divided by the same assumed inflation growth factor."],["Does it model changing inflation by year?","No. It assumes one constant annual rate."]],"tax":[["How is tax estimated?","The entered taxable amount is multiplied by the flat rate, then entered credits are applied."],["Can credits make tax negative?","No. Estimated tax is floored at zero."],["Is this a jurisdiction-specific tax calculation?","No. It is a flat-rate illustration only."],["Are deductions automatically detected?","No. Enter the taxable amount yourself."]],"sales-tax":[["How is the discount applied?","The entered discount is applied to the pre-tax base."],["Can I enter a tax-inclusive amount?","Yes. Choose the included mode to extract the tax base before applying the discount."],["Are exemptions and local rules modeled?","No. The entered tax rate is applied as a simplified estimate."],["Is shipping taxed?","Shipping is not included in the tax base in this calculator."]],"vat-gst":[["Can I add VAT or GST?","Yes. Add mode calculates tax on the net amount and adds it."],["Can I remove tax from a gross amount?","Yes. Remove mode extracts the tax included in the entered gross amount."],["Are exemptions and registration rules included?","No. These vary by jurisdiction and transaction."],["What rate should I enter?","Use the applicable rate for your transaction after checking official local guidance."]],"tax-refund":[["How is an estimated refund calculated?","Withholding and credits are added, then estimated liability is subtracted."],["What if tax paid is below liability?","The difference is shown as an estimated amount due."],["Does this file a tax return?","No. It is only a planning calculation."],["Are penalties and interest included?","No. They are not modeled."]],"salary":[["How is take-home pay estimated?","Selected jurisdiction income tax, configured employee payroll contributions and entered deductions are subtracted from gross salary."],["Which tax profiles are supported?","Only the jurisdiction and tax-year profiles shown in the selector."],["Are all payroll exemptions included?","No. Special exemptions, year-to-date pay and pay-period rounding may differ."],["Is the result an official payslip?","No. It is an educational estimate."]],"paycheck":[["How is overtime pay calculated?","Overtime hours multiplied by hourly rate and the entered overtime multiplier."],["What deductions are included?","The entered flat withholding, retirement percentage, benefits and other deductions."],["Does it determine legal overtime eligibility?","No. Employment rules vary by jurisdiction."],["Can bonuses be included?","Yes. Enter bonus or commission for the pay period."]],"payroll":[["What employer costs are included?","Gross wages, entered employer tax percentage, per-employee benefits and other monthly costs."],["Does it calculate statutory payroll taxes?","No. It uses the employer percentage you enter."],["How is annual cost estimated?","The monthly total is multiplied by 12."],["Are contractor costs included?","Only if included in the employee count and average pay inputs."]],"overtime":[["How is overtime pay calculated?","Hourly rate multiplied by overtime hours and the selected multiplier."],["What is blended hourly rate?","Total gross earnings divided by regular plus overtime hours."],["Does this decide which hours legally qualify?","No. It uses the hour categories entered."],["Are taxes deducted?","No. The result is gross earnings before deductions."]],"discount":[["How is the coupon applied?","The coupon is applied after the first discount to the reduced price."],["When is tax calculated?","Tax is calculated on the discounted subtotal."],["Is shipping included?","Yes. The entered shipping cost is added after tax."],["Do all stores apply discounts this way?","No. Store-specific coupon, tax and shipping rules may differ."]],"exchange-fees":[["What is exchange-rate markup?","The difference between the entered mid-market rate and the customer rate applied by a provider."],["Which fees are included?","The entered fixed fee and percentage transfer fee."],["Are quotes live?","No. The calculation uses the rate and fees you enter."],["Are recipient bank fees included?","No. Recipient-side charges are excluded."]],"transfer-compare":[["How are providers compared?","Both hypothetical fee structures use the same entered mid-market rate and send amount."],["What determines the better result?","The provider with the higher estimated recipient amount."],["Are provider rates live?","No. Enter current quotes yourself for a meaningful comparison."],["Are delivery time and recipient fees included?","No. These should be checked with each provider."]],"markup":[["What is markup?","The markup amount divided by cost, expressed as a percentage."],["How is selling price calculated?","Cost multiplied by one plus the markup percentage."],["Is markup the same as gross margin?","No. Gross margin is markup amount divided by selling price."],["Can markup exceed 100%?","Yes. The engine allows up to its configured maximum."]],"mortgage":[["What does this payment include?","Principal and interest only; taxes, insurance and lender fees are excluded."],["How is the payment calculated?","The fixed-payment formula uses financed principal, monthly rate and payment count."],["Does an extra payment reduce interest?","Extra principal usually reduces future interest and payoff time."],["Why can lender figures differ?","Daily accrual, fees, payment dates and rounding may change actual figures."]],"amortization":[["What is amortization?","A schedule showing how payments repay principal and interest over time."],["Why is early interest higher?","Interest is calculated on the larger opening balance."],["How are yearly totals calculated?","Each year aggregates up to twelve monthly payment rows."],["Why can lender balances differ?","Daily interest, payment timing, fees and rounding rules may differ."]],"payoff":[["How is extra payment applied?","The model applies the extra amount to principal after the scheduled payment."],["How is interest saved calculated?","It simulates standard and accelerated schedules and compares total interest."],["Can I model a lump sum?","This version models recurring monthly extra payments only."],["Are prepayment fees included?","No. Check your lender agreement for fees and limits."]],"refinance":[["Are closing costs financed?","Yes. Entered closing costs are added to the new loan principal."],["What is break-even?","A simple estimate of closing costs divided by positive monthly payment savings."],["Can a lower payment cost more?","Yes. A longer term can lower payments but increase total interest."],["Are all refinance fees included?","Only the closing costs entered in the calculator are included."]],"student-loan":[["Does this model income-driven repayment?","No. It models fixed-rate level payments only."],["How does extra payment work?","The extra amount is assumed to reduce principal after the scheduled payment."],["Are forgiveness programs included?","No. Eligibility and forgiveness programs are not modeled."],["Why may servicer figures differ?","Accrual method, payment timing and servicer rules may change results."]]})[d.id];const fallbackFaqs=[["What does "+d.n+" calculate?",d.desc],["How do I use this calculator?","Enter the requested values, review the assumptions and adjust any input to update the result."],["Are results instant?","Yes. Calculations run in your browser and update when supported inputs change."],["Are my entries sent to a server?","No. Calculator inputs are processed in this browser; do not enter sensitive personal information."]];const faqs=d.seo?.faqs?.length?d.seo.faqs:batchFaqs?.length?batchFaqs:fallbackFaqs;return '<section class="panel seo-content"><h3>'+escapeHtml(toolUi("aboutCalculator","About this calculator"))+'</h3><p>'+escapeHtml(d.seo?.intro||d.desc)+'</p><h3>'+escapeHtml(toolUi("faq","Frequently asked questions"))+'</h3>'+faqs.map(f=>'<details><summary>'+escapeHtml(f[0])+'</summary><p>'+escapeHtml(f[1])+'</p></details>').join("")+'</section>'}
function geometryGraph(g){const el=$("#graph");el.className="";if(g.type==="circle"){const r=62;el.innerHTML='<svg viewBox="0 0 320 220" role="img" aria-label="Circle diagram showing radius"><circle cx="150" cy="108" r="'+r+'" fill="none" stroke="#23805a" stroke-width="3"/><line x1="150" y1="108" x2="212" y2="108" stroke="#b7791f" stroke-width="3"/><circle cx="150" cy="108" r="3" fill="#23805a"/><text x="181" y="98" font-size="12" fill="currentColor">r = '+num(g.radius,4)+'</text><text x="150" y="198" text-anchor="middle" font-size="11" fill="currentColor">Illustrative diagram · not to scale</text></svg>';return}if(g.type==="right-triangle"){el.innerHTML='<svg viewBox="0 0 320 220" role="img" aria-label="Right triangle showing two perpendicular sides and hypotenuse"><path d="M65 175 L65 45 L260 175 Z" fill="rgba(35,128,90,.08)" stroke="#23805a" stroke-width="3"/><path d="M65 157 H83 V175" fill="none" stroke="#b7791f" stroke-width="2"/><text x="45" y="112" text-anchor="end" font-size="12" fill="currentColor">a = '+num(g.a,4)+'</text><text x="162" y="194" text-anchor="middle" font-size="12" fill="currentColor">b = '+num(g.b,4)+'</text><text x="178" y="95" text-anchor="middle" font-size="12" fill="currentColor">c = '+num(g.c,4)+'</text><text x="160" y="215" text-anchor="middle" font-size="10" fill="currentColor">Illustrative diagram · not to scale</text></svg>';return}if(g.type==="triangle"){el.innerHTML='<svg viewBox="0 0 320 220" role="img" aria-label="Triangle area diagram showing base and perpendicular height"><path d="M55 175 L270 175 L205 42 Z" fill="rgba(35,128,90,.08)" stroke="#23805a" stroke-width="3"/><line x1="205" y1="42" x2="205" y2="175" stroke="#b7791f" stroke-width="2" stroke-dasharray="5 4"/><path d="M193 175 V163 H205" fill="none" stroke="#b7791f" stroke-width="2"/><text x="160" y="195" text-anchor="middle" font-size="12" fill="currentColor">Base = '+num(g.base,4)+'</text><text x="215" y="112" font-size="12" fill="currentColor">h = '+num(g.height,4)+'</text><text x="160" y="215" text-anchor="middle" font-size="10" fill="currentColor">Illustrative diagram · not to scale</text></svg>';return}el.className="chart-empty";el.textContent="No diagram is needed for this calculation."}
function scatterGraph(values,xValues,fitValues){const el=$("#graph"),points=values.map((y,i)=>({x:Number(xValues[i]),y:Number(y)})).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y));if(points.length<2){el.className="chart-empty";el.textContent="At least two finite coordinate pairs are needed for this graph.";return}const fit=Array.isArray(fitValues)?fitValues.map((y,i)=>({x:Number(xValues[i]),y:Number(y)})).filter(p=>Number.isFinite(p.x)&&Number.isFinite(p.y)).sort((a,b)=>a.x-b.x):[];if(window.Chart){el.className="chart-canvas";el.innerHTML='<canvas id="finance-chart" role="img" aria-label="Scatter plot of paired observations and fitted line"></canvas>';const datasets=[{label:"Observed pairs",data:points,showLine:false,pointRadius:4,backgroundColor:"#23805a"}];if(fit.length>1)datasets.push({label:"Least-squares fit",data:fit,showLine:true,pointRadius:0,borderColor:"#b7791f",borderWidth:2});activeChart=new Chart($("#finance-chart").getContext("2d"),{type:"scatter",data:{datasets},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:true}},scales:{x:{type:"linear",title:{display:true,text:"X"}},y:{title:{display:true,text:"Y"}}}}});return}const xs=points.map(p=>p.x),ys=points.map(p=>p.y),xmin=Math.min(...xs),xmax=Math.max(...xs),ymin=Math.min(...ys),ymax=Math.max(...ys),xr=xmax-xmin||1,yr=ymax-ymin||1,W=620,H=220,P=28,xy=p=>[P+(p.x-xmin)/xr*(W-2*P),H-P-(p.y-ymin)/yr*(H-2*P)],line=fit.length>1?'<polyline points="'+fit.map(p=>xy(p).map(v=>v.toFixed(1)).join(",")).join(" ")+'" fill="none" stroke="#b7791f" stroke-width="2"/>':"";el.className="";el.innerHTML='<svg viewBox="0 0 '+W+" "+H+'" role="img" aria-label="Scatter plot of paired observations and fitted line">'+line+points.map(p=>{const q=xy(p);return'<circle cx="'+q[0].toFixed(1)+'" cy="'+q[1].toFixed(1)+'" r="4" fill="#23805a"/>'}).join("")+"</svg>"}
function calendarGraph(c){const el=$("#graph");el.className="calendar-view";const names=c.weekStart==="monday"?["Mon","Tue","Wed","Thu","Fri","Sat","Sun"]:["Sun","Mon","Tue","Wed","Thu","Fri","Sat"],month=new Date(Date.UTC(c.year,c.month-1,1)).toLocaleDateString(undefined,{month:"long",timeZone:"UTC"}),cells=c.cells;let body="";for(let i=0;i<cells.length;i+=7){body+="<tr>"+cells.slice(i,i+7).map(day=>"<td>"+(day===null?"<span aria-hidden='true'> </span>":"<time datetime='"+c.year+"-"+String(c.month).padStart(2,"0")+"-"+String(day).padStart(2,"0")+"'>"+day+"</time>")+"</td>").join("")+"</tr>"}el.innerHTML="<table class='calendar-table'><caption>"+month+" "+c.year+" calendar · "+(c.weekStart==="monday"?"Monday":"Sunday")+" first</caption><thead><tr>"+names.map(n=>"<th scope='col'>"+n+"</th>").join("")+"</tr></thead><tbody>"+body+"</tbody></table>"}
function graph(s,unit,labels,type,fitSeries,geometry,calendar){let el=$("#graph");if(activeChart){activeChart.destroy();activeChart=null}if(calendar){calendarGraph(calendar);return}if(geometry){geometryGraph(geometry);return}if((type==="bar"||type==="scatter")&&!window.Chart&&!window.__finpulseChartLoading){window.__finpulseChartLoading=true;const script=document.createElement("script");script.src="https://cdn.jsdelivr.net/npm/chart.js@4.5.1/dist/chart.umd.min.js";script.integrity="sha384-jb8JQMbMoBUzgWatfe6COACi2ljcDdZQ2OxczGA3bGNeWe+6DChMTBJemed7ZnvJ";script.crossOrigin="anonymous";script.onload=()=>{window.__finpulseChartLoading=false;graph(s,unit,labels,type,fitSeries,geometry,calendar)};script.onerror=()=>{window.__finpulseChartLoading=false};document.head.appendChild(script);return}if(type==="scatter"){scatterGraph(s,labels,fitSeries);return}if(!s||s.length<2){el.className="chart-empty";el.textContent="No time-series graph is needed for this calculation. Your numerical breakdown is shown above.";return}const data=s.filter(Number.isFinite),names=labels&&labels.length===data.length?labels:data.map((_,i)=>"Period "+(i+1));if(window.Chart){el.className="chart-canvas";el.innerHTML='<canvas id="finance-chart" role="img" aria-label="Illustrative calculator chart"></canvas>';activeChart=new Chart($("#finance-chart").getContext("2d"),{type:type==="bar"?"bar":"line",data:{labels:names,datasets:[{label:unit||"Amount",data,borderColor:"#23805a",backgroundColor:type==="bar"?"rgba(35,128,90,.22)":"rgba(35,128,90,.12)",borderWidth:2,fill:type!=="bar",tension:.25,pointRadius:data.length>18?0:3}]},options:{responsive:true,maintainAspectRatio:false,animation:false,plugins:{legend:{display:false},tooltip:{callbacks:{label:ctx=>unit?num(ctx.parsed.y,4)+" "+unit:fmt(ctx.parsed.y)}}},scales:{y:{beginAtZero:false,ticks:{callback:v=>unit?num(v,3)+" "+unit:fmt(v)}}}}});return}let w=620,h=175,p=30,min=Math.min(...data),max=Math.max(...data),range=max-min||1,axis=v=>unit?num(v,4)+" "+unit:new Intl.NumberFormat(activeCurrency==="BDT"?"en-BD":undefined,{style:"currency",currency:displayCurrencyCode(),notation:"compact",maximumFractionDigits:1}).formatToParts(v).map(p=>p.type==="currency"?Smart.currencySymbol(displayCurrencyCode()):p.value).join(""),pts=data.map((v,i)=>[p+i*(w-2*p)/(data.length-1),h-p-(v-min)/range*(h-2*p)]),path=pts.map((x,i)=>(i?"L":"M")+x[0].toFixed(1)+" "+x[1].toFixed(1)).join(" ");el.className="";el.innerHTML='<svg viewBox="0 0 '+w+' '+h+'" role="img" aria-label="Illustrative balance trend"><path d="M'+p+' '+p+'H'+(w-p)+' M'+p+' '+h/2+'H'+(w-p)+' M'+p+' '+(h-p)+'H'+(w-p)+'" stroke="#e4ece5" stroke-dasharray="4 5" fill="none"/><path d="'+path+'" fill="none" stroke="#23805a" stroke-width="3" stroke-linecap="round"/><text x="'+p+'" y="13" fill="#53675b" font-size="10">'+axis(max)+'</text><text x="'+p+'" y="'+(h-3)+'" fill="#53675b" font-size="10">'+axis(min)+'</text><text x="'+(w-p)+'" y="'+(h-3)+'" text-anchor="end" fill="#53675b" font-size="10">Time →</text></svg>'}

